inal_tokens_reported`, `terminal_tokens_used`, `terminal_at` FROM `session_input_queue`;
-- drop "session_input_queue" table after copying rows
DROP TABLE `session_input_queue`;
-- rename temporary table "new_session_input_queue" to "session_input_queue"
ALTER TABLE `new_session_input_queue` RENAME TO `session_input_queue`;
-- create index "idx_session_input_queue_generation" to table: "session_input_queue"
CREATE INDEX `idx_session_input_queue_generation` ON `session_input_queue` (`session_id`, `session_generation`, `status`);
-- create index "idx_session_input_queue_goal_owner" to table: "session_input_queue"
CREATE INDEX `idx_session_input_queue_goal_owner` ON `session_input_queue` (`loop_run_id`, `task_run_id`, `owner_epoch`, `status`, `dispatchable`, `fence_kind`);
-- create index "idx_session_input_queue_pending" to table: "session_input_queue"
CREATE INDEX `idx_session_input_queue_pending` ON `session_input_queue` (`session_id`, `status`, `delivery` DESC, `priority` DESC, `enqueued_at`, `id`);
-- create index "uq_session_input_queue_prompt_admission" to table: "session_input_queue"
CREATE UNIQUE INDEX `uq_session_input_queue_prompt_admission` ON `session_input_queue` (`prompt_admission_id`) WHERE prompt_admission_id IS NOT NULL;
-- create index "uq_session_input_queue_active_steer" to table: "session_input_queue"
CREATE UNIQUE INDEX `uq_session_input_queue_active_steer` ON `session_input_queue` (`session_id`) WHERE mode = 'steer' AND status = 'queued';
-- create index "uq_session_input_queue_goal_prompt" to table: "session_input_queue"
CREATE UNIQUE INDEX `uq_session_input_queue_goal_prompt` ON `session_input_queue` (`loop_run_id`, `prompt_id`) WHERE prompt_id IS NOT NULL;
-- create index "uq_session_input_queue_synthetic_message" to table: "session_input_queue"
CREATE UNIQUE INDEX `uq_session_input_queue_synthetic_message` ON `session_input_queue` (`session_id`, `message_id`) WHERE owner_kind = 'synthetic' AND message_id <> '' AND status IN ('queued','dispatching');
-- create "session_subagent_wakes" table
CREATE TABLE `session_subagent_wakes` (`wake_message_id` text NULL, `workspace_id` text NOT NULL, `parent_session_id` text NOT NULL, `state` text NOT NULL, `route` text NOT NULL, `input_entry_id` text NOT NULL DEFAULT '', `steer_requeued` integer NOT NULL DEFAULT 0, `attempts` integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), `created_at` text NOT NULL, `updated_at` text NOT NULL, PRIMARY KEY (`wake_message_id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `parent_session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE CASCADE, CHECK (state IN ('open','dispatched','settled','canceled')), CHECK (route IN ('queue','steer')));
CREATE INDEX `idx_session_subagent_wakes_parent_state` ON `session_subagent_wakes` (`parent_session_id`, `state`);
-- create index "uq_session_subagent_wakes_open" to table: "session_subagent_wakes"
CREATE UNIQUE INDEX `uq_session_subagent_wakes_open` ON `session_subagent_wakes` (`parent_session_id`) WHERE state = 'open';
-- create "session_subagents" table
CREATE TABLE `session_subagents` (`id` text NULL, `workspace_id` text NOT NULL, `parent_session_id` text NOT NULL, `parent_turn_id` text NOT NULL, `parent_tool_call_id` text NOT NULL DEFAULT '', `child_session_id` text NULL, `origin` text NOT NULL, `provider_tool_call_id` text NOT NULL DEFAULT '', `idempotency_key` text NOT NULL, `request_fingerprint` text NOT NULL, `title` text NOT NULL, `role` text NOT NULL DEFAULT 'general', `task_chars` integer NOT NULL, `pending_task` text NULL, `runtime_agent` text NOT NULL DEFAULT '', `runtime_provider` text NOT NULL DEFAULT '', `runtime_model` text NOT NULL DEFAULT '', `runtime_reasoning_effort` text NOT NULL DEFAULT '', `runtime_speed` text NOT NULL DEFAULT '', `depth` integer NOT NULL, `status` text NOT NULL, `work_state` text NOT NULL, `progress` text NOT NULL DEFAULT '', `result` text NULL, `result_truncated` integer NOT NULL DEFAULT 0, `error` text NULL, `wake_policy` text NOT NULL, `delivery` text NOT NULL DEFAULT 'none', `wake_message_id` text NULL, `acknowledged_turn_id` text NOT NULL DEFAULT '', `started_at` text NULL, `settled_at` text NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `parent_session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT `1` FOREIGN KEY (`wake_message_id`) REFERENCES `session_subagent_wakes` (`wake_message_id`) ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT `2` FOREIGN KEY (`child_session_id`) REFERENCES `sessions` (`id`) ON UPDATE NO ACTION ON DELETE SET NULL, CHECK (origin IN ('delegated','provider_native')), CHECK (length(title) <= 512), CHECK (depth >= 1), CHECK (status IN ('queued','running','waiting','completed','failed','canceled','interrupted')), CHECK (work_state IN ('working','waiting_for_children','result_available')), CHECK (length(progress) <= 280), CHECK (wake_policy IN ('always','settled_only')), CHECK (delivery IN ('none','pending','claimed','delivered','acknowledged','disposed')));
-- create index "session_subagents_child_session_id" to table: "session_subagents"
CREATE UNIQUE INDEX `session_subagents_child_session_id` ON `session_subagents` (`child_session_id`);
-- create index "session_subagents_parent_session_id_idempotency_key" to table: "session_subagents"
CREATE UNIQUE INDEX `session_subagents_parent_session_id_idempotency_key` ON `session_subagents` (`parent_session_id`, `idempotency_key`);
-- create index "idx_session_subagents_parent_created" to table: "session_subagents"
CREATE INDEX `idx_session_subagents_parent_created` ON `session_subagents` (`parent_session_id`, `created_at`);
-- create index "idx_session_subagents_workspace_status" to table: "session_subagents"
CREATE INDEX `idx_session_subagents_workspace_status` ON `session_subagents` (`workspace_id`, `status`);
-- create index "idx_session_subagents_parent_delivery" to table: "session_subagents"
CREATE INDEX `idx_session_subagents_parent_delivery` ON `session_subagents` (`parent_session_id`, `delivery`) WHERE delivery IN ('pending','claimed');
-- create index "idx_session_subagents_provider_tool" to table: "session_subagents"
CREATE INDEX `idx_session_subagents_provider_tool` ON `session_subagents` (`parent_session_id`, `provider_tool_call_id`) WHERE origin = 'provider_native';
-- enable back the enforcement of foreign-keys constraints
PRAGMA foreign_keys = on;
